// Planifie jusqu'à 21 contenus (3 slots × 7 jours) en distribution équilibrée par plateforme.
// Slots 9h / 13h / 18h UTC (= Dakar GMT+0). Max 1 post par plateforme par jour.

const all = $input.all().map(i => i.json);
// Tri par createdTime asc (on priorise les plus anciens dans le backlog)
all.sort((a, b) => (a.createdTime || '').localeCompare(b.createdTime || ''));

const SLOTS = [9, 13, 18];
const DAYS = 7;
const MAX = SLOTS.length * DAYS; // 21

// Grouper par plateforme
const byPlatform = {};
for (const it of all) {
  const p = (it.Plateforme_Principale || 'instagram').toLowerCase();
  (byPlatform[p] = byPlatform[p] || []).push(it);
}
const platforms = Object.keys(byPlatform);

// Round-robin inter-plateformes pour équilibrer
const queue = [];
let stillHasWork = true;
while (stillHasWork && queue.length < MAX) {
  stillHasWork = false;
  for (const p of platforms) {
    if (byPlatform[p].length) {
      queue.push(byPlatform[p].shift());
      stillHasWork = true;
      if (queue.length >= MAX) break;
    }
  }
}

// Assigner (jour, slot) — max 1 post/plateforme/jour
const now = new Date();
const results = [];
const usedDayPlatform = new Set();
let slotCursor = 0;

for (const item of queue) {
  const p = (item.Plateforme_Principale || 'instagram').toLowerCase();
  let placed = false;
  for (let sc = slotCursor; sc < MAX; sc++) {
    const day = Math.floor(sc / SLOTS.length) + 1;
    const key = `${day}:${p}`;
    if (!usedDayPlatform.has(key)) {
      const hour = SLOTS[sc % SLOTS.length];
      const d = new Date(now);
      d.setUTCDate(now.getUTCDate() + day);
      d.setUTCHours(hour, 0, 0, 0);
      results.push({ json: {
        id: item.id,
        Status: 'planifié',
        Date_Publication_Prevue: d.toISOString()
      }});
      usedDayPlatform.add(key);
      if (sc === slotCursor) slotCursor++;
      placed = true;
      break;
    }
  }
  if (!placed) break;
}

return results;
